INSERT INTO public.chapters (book_id, chapter_number, title, slug, description, source_page, display_order) SELECT b.id, x.chapter_number, x.title, x.slug, x.description, x.source_page, x.display_order FROM (VALUES (42, 'আন্তর্জাতিক ক্ষেত্রে বাংলাদেশ', 'bangladesh-international-relations', 'Source-derived Bangladesh international-relations material with explicit verification states.', 479, 42), (43, 'বাংলাদেশের চুক্তি', 'bangladesh-treaties', 'Source-derived Bangladesh treaty and accord material with explicit verification states.', 482, 43)) AS x(chapter_number, title, slug, description, source_page, display_order) JOIN public.books b ON b.title = 'Jubayer''s GK' WHERE NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.book_id = b.id AND c.slug = x.slug);
INSERT INTO public.topics (chapter_id, title, slug, description, source_page, display_order) SELECT c.id, x.title, x.slug, x.description, x.source_page, x.display_order FROM (VALUES ('bangladesh-international-relations', 'জাতিসংঘ ও আন্তর্জাতিক সংস্থা', 'un-and-international-organisations', 'Source-derived UN, Commonwealth, and organisation reference material.', 479, 1), ('bangladesh-international-relations', 'আন্তর্জাতিক সম্পর্কভিত্তিক বিগত বছরের প্রশ্ন', 'international-relations-past-exam-mcqs', 'Past-exam MCQs with all printed options, answer keys, and exam labels.', 480, 2), ('bangladesh-treaties', 'বাংলাদেশের গুরুত্বপূর্ণ চুক্তি', 'bangladesh-treaties-reference', 'Source-derived bilateral and multilateral treaty reference material.', 482, 1), ('bangladesh-treaties', 'চুক্তি সম্পর্কিত বিগত বছরের প্রশ্ন', 'treaties-past-exam-mcqs', 'Past-exam MCQs with all printed options, answer keys, and exam labels.', 483, 2)) AS x(chapter_slug, title, slug, description, source_page, display_order) JOIN public.chapters c ON c.slug = x.chapter_slug AND c.book_id = (SELECT id FROM public.books WHERE title = 'Jubayer''s GK' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.chapter_id = c.id AND t.slug = x.slug);
