('482', 'bangladesh-treaties', 'bangladesh-treaties-reference', 'কতিপয় গুরুত্বপূর্ণ চুক্তি', 'Extradition Treaty হল- অপরাধী প্রত্যর্পণ চুক্তি।', 'medium', 'b9a4bc8f37f59db82f5f70ae59c5a1facf415fdf327b669623f8480c3a71fac6', 'source_attributed')) INSERT INTO public.gk_facts (book_id, chapter_id, topic_id, title, fact_text, explanation, source_page, source_section, source_excerpt, importance, confidence, canonical_hash) SELECT b.id, c.id, t.id, d.title, d.fact_text, CASE d.status WHEN 'verified' THEN 'Directly corroborated by a source in the batch verification ledger; original wording is retained.' ELSE 'Source-attributed material retained with explicit verification status and source linkage.' END, d.source_page::integer, d.title, d.fact_text, 3, d.confidence::confidence_level, d.canonical_hash FROM data d JOIN public.books b ON b.title = 'Jubayer''s GK' JOIN public.chapters c ON c.book_id = b.id AND c.slug = d.chapter_slug JOIN public.topics t ON t.chapter_id = c.id AND t.slug = d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET fact_text = EXCLUDED.fact_text, explanation = EXCLUDED.explanation, confidence = EXCLUDED.confidence;
